 private val app get()=RuntimeEnvironment.getApplication() as CaptureApplication
 private lateinit var repo:CaptureRepository
 private lateinit var gateway:DirectShopifyGateway;private lateinit var credentials:SecureCredentialStore;private lateinit var operationVault:ShopifyUploadVault
 private val location="gid://shopify/Location/1"
 @Before fun setup() {WorkManagerTestInitHelper.initializeTestWorkManager(app,Configuration.Builder().setExecutor(java.util.concurrent.Executor {}).setTaskExecutor(SynchronousExecutor()).build());repo=CaptureRepository(app,Room.inMemoryDatabaseBuilder(app,CaptureJournal::class.java).allowMainThreadQueries().build()) {d->java.nio.channels.FileChannel.open(d.toPath(),java.nio.file.StandardOpenOption.READ).use {it.force(true)}};app.repository=repo;repo.preferences.edit().clear().putBoolean("barcode",false).putBoolean("shopifyDirect",true).putBoolean("shopifyPaired",true).putBoolean("shopifyOwnerWrites",true).commit();val key=KeyGenerator.getInstance("AES").apply {init(256)}.generateKey();credentials=SecureCredentialStore(app,"production-fixture-${newId()}") {key};operationVault=ShopifyUploadVault(app) {key};gateway=DirectShopifyGateway(app,credentials,okhttp3.OkHttpClient(),operationVault);gateway.save("fixture.myshopify.com",newId(),"fixture-secret");repo.directShopifyFactory={gateway}}
 @After fun close() {repo.journal.close()}
 private fun health()=JSONObject().put("shopId","gid://shopify/Shop/1").put("shop","fixture.myshopify.com").put("currency","CAD").put("developmentStore",false).put("direct",true).put("allowProduction",true).put("publications",JSONArray()).put("locations",JSONArray().put(JSONObject().put("id",location).put("isActive",true)))
 private suspend fun inventory(count:Int):List<InventoryRow> {repo.start("Production fixture","A1");val session=repo.dao.active()!!;val first=repo.current();val b=Bitmap.createBitmap(30,40,Bitmap.Config.ARGB_8888);val bytes=java.io.ByteArrayOutputStream().use {b.compress(Bitmap.CompressFormat.JPEG,90,it);it.toByteArray()};b.recycle()
  return (0 until count).map {i->val g=if(i==0) first else GroupRow(sessionId=session.id,number=i+1,closed=true,location="A1").also {repo.dao.insert(it)};val item=repo.ensureInventoryItem(g);val photo=PhotoRow(groupId=g.id,position=0,role="FRONT",state="READY",scanState="OFF",bytes=bytes.size.toLong(),sha256=sha256(bytes));repo.original(photo.id).writeBytes(bytes);repo.dao.insert(photo);repo.saveInventory(item.copy(title="Alien",releaseYear=1979,condition="Good",description="An actual copy",priceCents=1200),item.revision)}
 }
 private suspend fun unprice(item:InventoryRow,title:String="Alien",edition:String="",year:Int?=1979):InventoryRow=repo.saveInventory(item.copy(title=title,priceCents=null,edition=edition,releaseYear=year),item.revision)
 private suspend fun sold() {val date=LocalDate.now().minusDays(2);val file=File(app.cacheDir,"production-${newId()}.csv");file.writeText("id,title,site,item_id,date_sold,sale_price,shipping_price,currency,url,edition,release_year,condition\n"+(1..5).joinToString("\n") {i->"$i,Alien 1979 VHS,EBAY_US,${1000+i},$date,${if(i==5) 100 else 8+i},2,CAD,https://www.ebay.com/itm/${1000+i},,1979,Good"}+"\n20,Alien Special Edition 1979 VHS,EBAY_US,2000,$date,90,2,CAD,https://www.ebay.com/itm/2000,Special Edition,1979,Good\n21,Alien 1979 VHS lot of 2,EBAY_US,2001,$date,200,2,CAD,https://www.ebay.com/itm/2001,,1979,Good\n22,Alien 2003 VHS,EBAY_US,2002,$date,300,2,CAD,https://www.ebay.com/itm/2002,,2003,Good\n23,Aliens 1986 VHS,EBAY_US,2003,$date,400,2,CAD,https://www.ebay.com/itm/2003,,1986,Good\n24,Alien 1979 VHS,EBAY_US,2004,$date,10,2,USD,https://www.ebay.com/itm/2004,,1979,Good\n25,Alien 1979 VHS sealed,EBAY_US,2005,$date,500,2,CAD,https://www.ebay.com/itm/2005,,1979,Sealed\n");repo.commitMarket(repo.previewMarket(file,file.name));file.delete()}
 @Test fun selectsSevenOfFiftyAndOnlyQueuesThoseSevenWithoutAnyReview():Unit=runBlocking {val items=inventory(50);val selected=items.filterIndexed {index,_->index%7==0}.take(7).map {it.groupId}.toSet();assertEquals(7,selected.size);val result=repo.submitSelectedDrafts(selected,health(),gateway.endpoint(),location,emptySet());assertTrue(result.skipped.toString(),result.skipped.isEmpty());assertEquals(1,result.jobs.size);assertEquals(selected,repo.journal.shopifyDao().items(result.jobs.single()).map {it.groupId}.toSet());assertTrue(repo.journal.shopifyDao().watchReviews().first().isEmpty());assertTrue(items.filter {it.groupId !in selected}.all {repo.journal.inventoryDao().item(it.groupId)!!.revision==it.revision});assertEquals(0,repo.journal.shopifyDao().items(result.jobs.single()).count {it.state=="SUCCESS"})
  val job=repo.journal.shopifyDao().job(result.jobs.single())!!;val remotes=mutableListOf<NativeShopifyFakeApi>()
  for((index,row) in repo.journal.shopifyDao().items(job.id).withIndex()) {val api=NativeShopifyFakeApi(100L+index*10).also {it.sku=row.itemId;it.creationKey=row.creationKey};remotes+=api;gateway=DirectShopifyGateway(app,credentials,okhttp3.OkHttpClient.Builder().addInterceptor(api).build(),operationVault);ShopifyPipeline(repo,gateway,operationVault).run(job,row)}
  assertEquals(7,remotes.sumOf {it.creations});assertEquals(7,remotes.sumOf {it.uploads});assertEquals(7,repo.journal.inventoryDao().items().count {it.shopifyState=="UPLOADED_AS_DRAFT"});assertTrue(repo.journal.shopifyDao().items(job.id).all {it.state=="SUCCESS"});assertTrue(remotes.all {it.status=="DRAFT" && !it.published});assertEquals(7,repo.journal.inventoryDao().items().filter {it.shopifyState=="UPLOADED_AS_DRAFT"}.map {it.shopifyProductId}.distinct().size)
}
 @Test fun fiftyDraftsUseOneOperatorActionAndNoPerItemApprovalReceipts():Unit=runBlocking {val all=inventory(50);val result=repo.submitSelectedDrafts(all.map {it.groupId}.toSet(),health(),gateway.endpoint(),location,emptySet());assertTrue(result.skipped.isEmpty());assertEquals(50,repo.journal.shopifyDao().items(result.jobs.single()).size);assertEquals(0,repo.journal.shopifyDao().watchReviews().first().size);assertEquals("CREATE_DRAFT",repo.journal.shopifyDao().job(result.jobs.single())!!.kind)}
 @Test fun invalidAndExistingPublishedCopiesAreSkippedWithoutBlockingGoodCopies():Unit=runBlocking {val all=inventory(3);val invalid=unprice(all[1]);val published=all[2].copy(shopifyProductId="gid://shopify/Product/77",shopifyState="PUBLISHED");repo.journal.inventoryDao().update(published);val result=repo.submitSelectedDrafts(all.map {it.groupId}.toSet(),health(),gateway.endpoint(),location,emptySet());assertEquals(setOf(invalid.groupId,published.groupId),result.skipped.keys);assertEquals(listOf(all[0].groupId),repo.journal.shopifyDao().items(result.jobs.single()).map {it.groupId});assertEquals(published,repo.journal.inventoryDao().item(published.groupId))}
 @Test fun exactAndApproximateSearchResultsCoexistAndRetainCompleteSalesCounts():Unit=runBlocking {sold();val page=repo.searchMarket(MarketFilters(query="Alien",currency="CAD"));assertTrue(page.groups.size>1);assertTrue(page.groups.any {it.title.contains("1979")});assertTrue(page.groups.any {it.matchTier=="POSSIBLE"});assertTrue(page.groups.all {it.matchReason.isNotBlank()});assertTrue(page.groups.first {it.title=="Alien 1979 VHS"}.samples==5L);assertTrue(hybridMarketScore("Alien","Alien").second=="EXACT");assertTrue(hybridMarketScore("Alien","Alien Special Edition",1979,1979).first<hybridMarketScore("Alien","Alien",1979,1979).first)}
 @Test fun mixedBatchPricesOfflineWithZeroModelRequestsAndManualProtection():Unit=runBlocking {sold();val all=inventory(5);val exact=unprice(all[0]);val typo=unprice(all[1],"Aliern");val absent=unprice(all[2],"This Movie Does Not Exist");val edition=unprice(all[3],"Alien","Special Edition");var calls=0;val id=repo.queueProduction(all.map {it.groupId}.toSet(),"MATCH_PRICE",AutoPriceRules(minimum=3).json());repo.runProduction(id) {_,_,_,_,_->calls++;error("Offline pricing must never call a model")};assertEquals(0,calls);val results=repo.journal.productionDao().items(id).associateBy {it.groupId};assertEquals("HIGH_CONFIDENCE",results.getValue(exact.groupId).state);assertEquals("NEEDS_REVIEW",results.getValue(typo.groupId).state);assertTrue(results.getValue(absent.groupId).state in setOf("NEEDS_REVIEW","NO_RELIABLE_MATCH"));assertNotEquals("HIGH_CONFIDENCE",results.getValue(edition.groupId).state);assertEquals("NEEDS_REVIEW",results.getValue(all[4].groupId).state);assertEquals(1200L,repo.journal.inventoryDao().item(all[4].groupId)!!.priceCents);assertNull(repo.journal.inventoryDao().item(exact.groupId)!!.priceCents)
  val result=results.getValue(exact.groupId);val data=JSONObject(result.resultJson);assertEquals(4,data.getInt("count"));assertEquals(1,data.getJSONArray("excludedOutliers").length());assertEquals(1250L,data.getLong("priceCents"));val applied=repo.applyProductionPrices(setOf(result.id));assertEquals(1,applied.first);assertTrue(applied.second.isEmpty());val saved=repo.journal.inventoryDao().item(exact.groupId)!!;assertEquals(1250L,saved.priceCents);assertTrue(saved.priceSource.startsWith("MARKET_AUTO_"));assertEquals(1,repo.journal.marketDao().decisionsForItem(exact.groupId).count {it.method=="AUTO_MEDIAN"});assertEquals(0,calls)
 }
 @Test fun automaticHighConfidenceApplyIsExplicitAndDoesNotPriceQuestionableMatches():Unit=runBlocking {sold();val all=inventory(2);val good=unprice(all[0]);val typo=unprice(all[1],"Aliern");val id=repo.queueProduction(setOf(good.groupId,typo.groupId),"MATCH_PRICE",AutoPriceRules(automatic=true).json());repo.runProduction(id) {_,_,_,_,_->error("No AI")};val results=repo.journal.productionDao().items(id);assertEquals("APPLIED",results.first {it.groupId==good.groupId}.state);assertNull(repo.journal.inventoryDao().item(typo.groupId)!!.priceCents);val revision=repo.journal.inventoryDao().item(good.groupId)!!.revision;repo.runProduction(id);assertEquals(revision,repo.journal.inventoryDao().item(good.groupId)!!.revision)}
 @Test fun fxIsExplicitDatedAndStatisticalRulesKeepRealEvidence():Unit=runBlocking {sold();val item=unprice(inventory(1).single());val cad=repo.buildAutoPrice(item,AutoPriceRules(shipping="EXCLUDE",floor=1500,ceiling=1600,roundingCents=100));assertEquals(1500L,cad.getLong("priceCents"));assertEquals(4,cad.getJSONArray("evidence").length());val converted=repo.buildAutoPrice(item,AutoPriceRules(usdCad="1.35",rateDate=LocalDate.now().toString(),outliers="NONE",method="TRIMMED_MEAN"));assertEquals(6,converted.getInt("count"));assertEquals("1.35",converted.getJSONObject("rules").getString("usdCad"));try {AutoPriceRules(usdCad="1.35").validate();fail()} catch(_:Exception) {};try {AutoPriceRules(usdCad="1.35",rateDate=LocalDate.now().plusDays(1).toString()).validate();fail()} catch(_:Exception) {};assertEquals(250L,aggregateAutoPrice(listOf("1","2","3","100").map {it.toBigDecimal()},"MEDIAN"));assertEquals(550L,aggregateAutoPrice((1..10).map {it.toBigDecimal()},"TRIMMED_MEAN"))}
 @Test fun changedInventoryAndSupersededEvidenceCannotApplyAStalePrice():Unit=runBlocking {sold();val item=unprice(inventory(1).single());val id=repo.queueProduction(setOf(item.groupId),"MATCH_PRICE",AutoPriceRules().json());repo.runProduction(id);val row=repo.journal.productionDao().items(id).single();repo.saveInventory(item.copy(title="Aliens"),item.revision);assertEquals(0,repo.applyProductionPrices(setOf(row.id)).first);assertNull(repo.journal.inventoryDao().item(item.groupId)!!.priceCents)}
 @Test fun changedSourceEvidenceCannotApplySavedRecommendation():Unit=runBlocking {sold();val item=unprice(inventory(1).single());val id=repo.queueProduction(setOf(item.groupId),"MATCH_PRICE",AutoPriceRules().json());repo.runProduction(id);val row=repo.journal.productionDao().items(id).single();val source=JSONObject(row.resultJson).getJSONArray("evidence").getJSONObject(0).getString("id");repo.journal.openHelper.writableDatabase.execSQL("UPDATE market_sales SET current=0 WHERE id=?",arrayOf(source));assertEquals(0,repo.applyProductionPrices(setOf(row.id)).first);assertNull(repo.journal.inventoryDao().item(item.groupId)!!.priceCents)}
 @Test fun immutableEvidenceHistorySurvivesPricingAndInvalidEditionsAreExcluded():Unit=runBlocking {sold();val item=unprice(inventory(1).single());val before=repo.journal.openHelper.writableDatabase.query("SELECT COUNT(*) FROM market_sales").use {it.moveToFirst();it.getInt(0)};val result=repo.buildAutoPrice(item,AutoPriceRules());val refs=result.getJSONArray("evidence");for(i in 0 until refs.length()) {val sale=repo.journal.marketDao().sale(refs.getJSONObject(i).getString("id"))!!;assertEquals(1979,sale.releaseYear);assertEquals("",sale.edition);assertFalse(sale.title.contains("lot"));assertFalse(sale.title.contains("sealed"));assertTrue(sale.url.startsWith("https://"))};val after=repo.journal.openHelper.writableDatabase.query("SELECT COUNT(*) FROM market_sales").use {it.moveToFirst();it.getInt(0)};assertEquals(before,after)}
 @Test fun taskModelOverridesPersistIndependentlyAndBudgetMathIsExplicit():Unit=runBlocking {repo.saveTaskModel(null,TaskModelChoice("gpt-4.1-mini"));repo.saveTaskModel(AiTask.CONTENT,TaskModelChoice("gpt-4.1",inputUsdPerMillion="2",outputUsdPerMillion="8"));repo.saveTaskModel(AiTask.MARKET,TaskModelChoice("gpt-4.1-nano"));assertEquals("gpt-4.1-mini",repo.taskModel(AiTask.RECOGNITION).model);assertEquals("gpt-4.1",repo.taskModel(AiTask.CONTENT).model);assertEquals("gpt-4.1-nano",repo.taskModel(AiTask.MARKET).model);val reopened=CaptureRepository(app,repo.journal,repo.dataRoot);assertEquals(repo.taskModel(AiTask.CONTENT),reopened.taskModel(AiTask.CONTENT));assertEquals("0.052",boundedBatchCost(repo.taskModel(AiTask.CONTENT)).stripTrailingZeros().toPlainString());repo.saveTaskModel(AiTask.MARKET,null);assertEquals("gpt-4.1-mini",repo.taskModel(AiTask.MARKET).model);assertEquals("gpt-4.1",repo.taskModel(AiTask.CONTENT).model)}
 @Test fun channelDefaultsAndBatchSelectionsSurviveReopeningWithoutCredentialsInSettings():Unit=runBlocking {val h=health().put("publications",JSONArray().put(JSONObject().put("id","gid://shopify/Publication/1").put("name","Online Store")).put(JSONObject().put("id","gid://shopify/Publication/2").put("name","POS")));assertEquals(setOf("gid://shopify/Publication/1"),repo.savedPublicationDefaults(h));repo.savePublicationDefaults(setOf("gid://shopify/Publication/1","gid://shopify/Publication/2"),h);val model=ProductionModel(app);model.selection("fixture",emptySet());model.setSelection(setOf("a","b"));model.selection("other",emptySet());model.selection("fixture",emptySet());assertEquals(setOf("a","b"),model.selected);assertEquals(2,CaptureRepository(app,repo.journal).savedPublicationDefaults(h).size)}
 @Test fun unknownCapabilitiesAndUnapprovedAiJobsAreRejectedBeforeAnyRequest():Unit=runBlocking {val item=inventory(1).single();try {repo.validateTaskModel(AiTask.EDITION,TaskModelChoice("unknown-image-model"));fail()} catch(_:IllegalStateException) {};try {repo.queueProduction(setOf(item.groupId),"AI_MATCH",JSONObject(),false);fail()} catch(_:IllegalStateException) {};assertTrue(repo.journal.productionDao().watchJobs().first().isEmpty())}
 @Test fun interruptedBillableJobsPauseAndNeverAutomaticallyRetry():Unit=runBlocking {val item=inventory(1).single();val d=repo.journal.productionDao();val job=ProductionJobRow(kind="AI_MATCH",state="RUNNING");val row=ProductionItemRow(jobId=job.id,groupId=item.groupId,revision=item.revision,state="RUNNING");d.insert(job);d.insert(row);repo.recoverProduction();assertEquals("PAUSED_REVIEW",d.job(job.id)!!.state);assertEquals("UNCERTAIN",d.item(row.id)!!.state);var calls=0;repo.runProduction(job.id) {_,_,_,_,_->calls++;error("Must stay idle")};assertEquals(0,calls)}
 @Test fun metadataUsesExistingServicesAndDoesNotInventFacts():Unit=runBlocking {val items=inventory(2);val blank=repo.saveInventory(items[0].copy(description=""),items[0].revision);val id=repo.queueProduction(items.map {it.groupId}.toSet(),"METADATA");repo.runProduction(id) {_,_,_,_,_->error("Offline metadata cannot call a model")};assertTrue(repo.journal.inventoryDao().item(blank.groupId)!!.description.contains("1979"));assertEquals(items[1].description,repo.journal.inventoryDao().item(items[1].groupId)!!.description);assertFalse(repo.journal.inventoryDao().item(blank.groupId)!!.description.contains("tested"));assertTrue(repo.journal.inventoryDao().history(blank.groupId).any {it.action=="EDITED"})}


 private suspend fun aiChoice(task:AiTask,model:String):TaskModelChoice {val key=KeyGenerator.getInstance("AES").apply {init(256)}.generateKey();SecureApiKeyStore(app,{key}).save("fixture-key-value-not-real");val choice=TaskModelChoice(model,inputUsdPerMillion="0.1",outputUsdPerMillion="0.4",maxOutput=256);repo.saveTaskModel(task,choice);repo.journal.nextDao().save(AiCapabilityRow(stableRowId("OPENAI/$model"),"OPENAI",model,model,supportsText=true,supportsImages=true,supportsTools=true,origin="OPENAI_DOCUMENTED_REGISTRY"));return choice}
 private fun aiOptions(choice:TaskModelChoice,budget:String="1",requests:Int=1)=JSONObject().put("model",choice.json()).put("authBinding",SecureApiKeyStore(app).bindingId()).put("budgetUsd",budget).put("maxRequests",requests).put("inputTokenBound",20000)
 @Test fun optionalAiBatchUsesSeparateSavedModelOneConsentAndNeverWritesPrices():Unit=runBlocking {
  sold();val items=inventory(2);val choice=aiChoice(AiTask.MARKET,"gpt-4.1-nano");repo.saveTaskModel(AiTask.RECOGNITION,TaskModelChoice("gpt-4.1"));val id=repo.queueProduction(items.map {it.groupId}.toSet(),"AI_MATCH",aiOptions(choice),true);var calls=0
  repo.runProduction(id) {selected,chat,messages,tools,_->calls++;assertEquals("gpt-4.1-nano",selected.model);assertEquals(selected.model,chat.model);assertEquals(0,tools.length());assertEquals("[]",messages.single().attachmentsJson);val input=JSONObject(messages.single().body);val candidate=input.getJSONArray("candidates").getJSONObject(0).getString("id");AiClient.Result(JSONObject().put("matches",JSONArray().put(JSONObject().put("id",candidate).put("confidence",.8).put("reason","Uncalibrated identity estimate"))).toString(),JSONArray(),"mock",100,10,"0.00001")}
  assertEquals(1,calls);assertTrue(repo.journal.productionDao().items(id).any {it.state=="ERROR" && it.error.contains("request-count")});assertTrue(items.all {repo.journal.inventoryDao().item(it.groupId)!!.priceCents==it.priceCents});repo.runProduction(id) {_,_,_,_,_->calls++;error("Must not restart")};assertEquals(1,calls);val messages=repo.journal.nextDao().watchChats().first().flatMap {repo.journal.nextDao().messages(it.id)};assertEquals("0.00001",messages.last().costUsd);assertEquals("gpt-4.1",repo.taskModel(AiTask.RECOGNITION).model)
 }
 @Test fun batchBudgetStopsBeforeDispatchAndContentWaitsForReview():Unit=runBlocking {
  val original=inventory(1).single();val item=repo.saveInventory(original.copy(description=""),original.revision);val choice=aiChoice(AiTask.CONTENT,"gpt-4.1-mini");val denied=repo.queueProduction(setOf(item.groupId),"AI_METADATA",aiOptions(choice,budget="0.000001"),true);var calls=0;repo.runProduction(denied) {_,_,_,_,_->calls++;error("Budget cannot send")};assertEquals(0,calls)
  val allowed=repo.queueProduction(setOf(item.groupId),"AI_METADATA",aiOptions(choice),true);repo.runProduction(allowed) {selected,_,_,_,_->calls++;assertEquals(choice,selected);AiClient.Result("{\"description\":\"Alien VHS. See photographs for this copy.\",\"tags\":[\"VHS\"]}",JSONArray(),"mock",50,20)};assertEquals(1,calls);assertEquals("",repo.journal.inventoryDao().item(item.groupId)!!.description);val r=repo.journal.productionDao().items(allowed).single();assertEquals("NEEDS_REVIEW",r.state);assertEquals(1,repo.applyProductionContent(setOf(r.id)).first);assertTrue(repo.journal.inventoryDao().item(item.groupId)!!.description.contains("See photographs"))
 }
 @Test fun exactBarcodeCorroboratesMinorOcrButNeverAnIncompatibleEdition():Unit=runBlocking {
  val item=inventory(1).single().copy(title="Aliern",releaseYear=1979,barcode="036000291452",edition="");val sale=MarketSaleRow(newId(),"fixture","a".repeat(64),title="Alien 1979 VHS",titleKey="alien 1979",barcode="036000291452",releaseYear=1979,soldDecimal="10",shippingDecimal="2",totalCents=1200,currency="CAD",soldAt=LocalDate.now().toString(),url="https://example.com/fixture",site="FIXTURE",sourceItemId="1",observedAt=LocalDate.now().toString(),importId=newId(),rawJson="{}")
  assertTrue(compatibleAutoIdentity(item,sale));assertFalse(compatibleAutoIdentity(item,sale.copy(edition="Special Edition")));assertFalse(compatibleAutoIdentity(item,sale.copy(title="Alien 1979 VHS lot of 2")));assertFalse(compatibleAutoIdentity(item,sale.copy(releaseYear=2003)));assertFalse(compatibleAutoIdentity(item,sale.copy(barcode="012345678901")));assertFalse(compatibleAutoIdentity(item.copy(title="Alien",condition="Sealed"),sale))
 }
 @Test fun deletingSelectedInventoryCancelsUnsentLocalWorkflowAndDoesNotReviveRecord():Unit=runBlocking {
  val item=inventory(1).single();val id=repo.queueProduction(setOf(item.groupId),"METADATA");repo.trashLocal("INVENTORY",item.groupId);repo.runProduction(id);assertTrue(repo.journal.inventoryDao().items().none {it.groupId==item.groupId});assertEquals("CANCELLED",repo.journal.productionDao().items(id).single().state)
 }
 @Test fun workflowPreferencesRoundTripExcludesSecretsAndOwnerAuthorization():Unit=runBlocking {
  repo.saveTaskModel(AiTask.CONTENT,TaskModelChoice("gpt-4.1",reasoning="low"));repo.saveAutoPriceRules(AutoPriceRules(minimum=5,floor=1500,usdCad="1.35",rateDate=LocalDate.now().toString()));repo.preferences.edit().putBoolean("shopifyOwnerLive",true).putStringSet("shopifyDefaultPublications",setOf("gid://shopify/Publication/1","gid://shopify/Publication/2")).commit()
  val exported=repo.exportWorkflowPreferences();assertFalse(exported.toString().contains("fixture-secret"));assertFalse(exported.toString().contains("shopifyOwnerLive"));repo.saveTaskModel(AiTask.CONTENT,TaskModelChoice("gpt-4.1-nano"));repo.preferences.edit().putBoolean("shopifyOwnerLive",false).commit();repo.restoreWorkflowPreferences(exported);assertEquals("gpt-4.1",repo.taskModel(AiTask.CONTENT).model);assertEquals(5,repo.autoPriceRules().minimum);assertEquals(2,repo.preferences.getStringSet("shopifyDefaultPublications",emptySet())!!.size);assertFalse(repo.preferences.getBoolean("shopifyOwnerLive",true));val snapshot=repo.hashSnapshotFiles(repo.buildSnapshot());assertTrue(snapshot.has("workflowSettings"));assertEquals(11,snapshot.getInt("schema"))
 }
 @Test fun schemaTenMigrationPreservesExistingRowsAndAddsWorkflowTables():Unit=runBlocking {val item=inventory(1).single();val db=repo.journal.openHelper.writableDatabase;db.execSQL("DROP TABLE production_items");db.execSQL("DROP TABLE production_jobs");db.execSQL("DROP TABLE shopify_channel_states");MIGRATION_10_11.migrate(db);assertEquals(item.itemId,repo.journal.inventoryDao().item(item.groupId)!!.itemId);assertTrue(repo.journal.productionDao().watchJobs().first().isEmpty());assertEquals("ok",db.query("PRAGMA integrity_check").use {it.moveToFirst();it.getString(0)})}
}
